def nth_good_integer(N: int) -> int:
    def generate_good_integers():
        digits = [0, 2, 4, 6, 8]
        queue = [0]
        while True:
            current = queue.pop(0)
            for digit in digits:
                new_number = current * 10 + digit
                if new_number != 0:
                    queue.append(new_number)
                    yield new_number

    generator = generate_good_integers()
    good_integer = None
    for _ in range(N):
        good_integer = next(generator)
    return good_integer
